AssistantMessageToolRequest(name='create', tool_call_id='tooluse_KSaJEOn4TjHrtgLyND0FG6', arguments={'file_text': '/* Base reset & tokens */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-page:       #0f1117;
  --bg-card:       #1a1d27;
  --bg-card-hover: #1f2335;
  --border:        #2e3148;
  --border-open:   #5b6af0;
  --text-primary:  #e8eaf6;
  --text-secondary:#9da3c8;
  --accent:        #7b8cff;
  --accent-hover:  #a0aaff;
  --focus-ring:    #7b8cff;
  --cat-icon:      #f6a623;
  --radius:        10px;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #0f1117;
  font-weight: 700;
  border-radius: var(--radius);
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus { top: 1rem; }

/* Page */
body {
  background: var(--bg-page);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  line-height: 1.6;
  min-height: 100vh;
  padding: 2rem 1rem 4rem;
}

header {
  text-align: center;
  padding: 3rem 1rem 2.5rem;
  max-width: 720px;
  margin: 0 auto 2.5rem;
}

header .cat-emoji {
  font-size: 3rem;
  display: block;
  margin-bottom: 0.75rem;
  aria-hidden: true;
}

h1 {
  font-size: clamp(1.75rem, 5vw, 2.75rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #a0aaff, #f6a623);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 0.5rem;
}

header p {
  color: var(--text-secondary);
  font-size: 1.05rem;
}

/* Main layout */
main {
  max-width: 720px;
  margin: 0 auto;
}

/* Each FAQ item */
.example {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  margin-bottom: 0.75rem;
  transition: border-color 0.2s, box-shadow 0.2s;
  overflow: hidden;
}

.example:has(button[aria-expanded="true"]) {
  border-color: var(--border-open);
  box-shadow: 0 0 0 1px var(--border-open);
}

/* Trigger heading */
.example h2 {
  font-size: 1rem;
}

.example h2 button {
  all: unset;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  padding: 1.1rem 1.25rem;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  cursor: pointer;
  background: transparent;
  text-align: left;
  border-radius: var(--radius);
  transition: background 0.15s, color 0.15s;
}

.example h2 button:hover {
  background: var(--bg-card-hover);
  color: var(--accent-hover);
}

.example h2 button:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: -2px;
  border-radius: calc(var(--radius) - 1px);
}

/* Chevron icon */
.chevron {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  color: var(--accent);
  transition: transform 0.25s ease;
}

button[aria-expanded="true"] .chevron {
  transform: rotate(180deg);
}

/* Answer panel */
.details {
  padding: 0 1.25rem 1.25rem;
  color: var(--text-secondary);
  font-size: 0.97rem;
  border-top: 1px solid var(--border);
  padding-top: 1rem;
  animation: fadeIn 0.2s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Respect reduced motion */
@media (prefers-reduced-motion: reduce) {
  .details { animation: none; }
  .chevron { transition: none; }
  .example { transition: none; }
  .example h2 button { transition: none; }
}

/* Forced colors / high contrast */
@media (forced-colors: active) {
  .example { border: 1px solid ButtonText; }
  .example h2 button { color: ButtonText; background: ButtonFace; }
  .example h2 button:focus-visible { outline: 2px solid Highlight; }
  .chevron { color: ButtonText; }
  .details { border-top: 1px solid ButtonText; color: ButtonText; }
}

/* Footer */
footer {
  text-align: center;
  margin-top: 3rem;
  color: var(--text-secondary);
  font-size: 0.85rem;
}
