  background: linear-gradient(135deg, #a0aaff, #f6a623);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 0.5rem;
}

header p {
  color: var(--text-secondary);
  font-size: 1.05rem;
}

/* Main layout */
main {
  max-width: 720px;
  margin: 0 auto;
}

/* Each FAQ item */
.example {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  margin-bottom: 0.75rem;
  transition: border-color 0.2s, box-shadow 0.2s;
  overflow: hidden;
}

.example:has(button[aria-expanded="true"]) {
  border-color: var(--border-open);
  box-shadow: 0 0 0 1px var(--border-open);
}

/* Trigger heading */
.example h2 {
  font-size: 1rem;
}

.example h2 button {
  all: unset;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  padding: 1.1rem 1.25rem;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  cursor: pointer;
  background: transparent;
  text-align: left;
  border-radius: var(--radius);
  transition: background 0.15s, color 0.15s;
}

.example h2 button:hover {
  background: var(--bg-card-hover);
  color: var(--accent-hover);
}

.example h2 button:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: -2px;
  border-radius: calc(var(--radius) - 1px);
}

/* Chevron icon */
.chevron {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  color: var(--accent);
  transition: transform 0.25s ease;
}

button[aria-expanded="true"] .chevron {
  transform: rotate(180deg);
}

/* Answer panel */
.details {
  padding: 0 1.25rem 1.25rem;
  color: var(--text-secondary);
  font-size: 0.97rem;
  border-top: 1px solid var(--border);
  padding-top: 1rem;
  animation: fadeIn 0.2s ease;
}

@keyframes fadeIn {
  from { transform: translateY(-4px); }
  to   { transform: translateY(0); }
}

/* Respect reduced motion */
@media (prefers-reduced-motion: reduce) {
  .details { animation: none; }
  .chevron { transition: none; }
  .example { transition: none; }
  .example h2 button { transition: none; }
}

/* Forced colors / high contrast */
@media (forced-colors: active) {
  .example { border: 1px solid ButtonText; }
  .example h2 button { color: ButtonText; background: ButtonFace; }
  .example h2 button:focus-visible { outline: 2px solid Highlight; }
  .chevron { color: ButtonText; }
  .details { border-top: 1px solid ButtonText; color: ButtonText; }
}

/* Footer */
footer {
  text-align: center;
  margin-top: 3rem;
  color: var(--text-secondary);
  font-size: 0.85rem;
}
