  document.querySelectorAll('.example h2 button[aria-expanded]').forEach((btn) => {
    const panel = btn.closest('.example').querySelector('.details');
    if (!panel) return;

    // Collapse on init so content stays visible in no-JS environments
    btn.setAttribute('aria-expanded', 'false');
    panel.hidden = true;

    btn.addEventListener('click', () => {
      const isOpen = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', String(!isOpen));
      panel.hidden = isOpen;
    });

    // Optional: Escape collapses an open panel and keeps focus on the trigger
    btn.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && btn.getAttribute('aria-expanded') === 'true') {
        btn.setAttribute('aria-expanded', 'false');
        panel.hidden = true;
      }
    });
  });
})();
